import SwiftUI
enum InstrumentTheme {static let background=Color(red:0.035,green:0.065,blue:0.075);static let panel=Color(red:0.07,green:0.105,blue:0.115)}
struct FieldCard<Content:View>:View {let title:String;@ViewBuilder var content:Content;var body:some View {VStack(alignment:.leading,spacing:14) {Text(title.uppercased()).font(.caption.monospaced()).foregroundStyle(.secondary);content}.padding(18).frame(maxWidth:.infinity,alignment:.leading).background(InstrumentTheme.panel,in:RoundedRectangle(cornerRadius:16)).overlay(RoundedRectangle(cornerRadius:16).stroke(.white.opacity(0.07)))}}
struct Metric:View {let label:String;let value:String;let unit:String;var body:some View {VStack(alignment:.leading,spacing:5) {Text(label).font(.caption).foregroundStyle(.secondary);HStack(alignment:.firstTextBaseline,spacing:4){Text(value).font(.title2.monospacedDigit().weight(.semibold));Text(unit).font(.caption).foregroundStyle(.secondary)}}}}
struct ProvenanceBadge:View {let simulated:Bool;var body:some View {Text(simulated ? "SIMULATED · DEMO DATA" : "RECORDED MEASUREMENTS").font(.caption2.monospaced().weight(.semibold)).padding(.horizontal,9).padding(.vertical,5).background(simulated ? Color.orange.opacity(0.15) : Color.mint.opacity(0.15),in:Capsule()).foregroundStyle(simulated ? .orange : .mint)}}
struct EmptyField:View {let title:String;let detail:String;let icon:String;var body:some View {VStack(spacing:14){Image(systemName:icon).font(.largeTitle).foregroundStyle(.mint);Text(title).font(.title3.weight(.semibold));Text(detail).font(.subheadline).foregroundStyle(.secondary).multilineTextAlignment(.center)}.padding(28).frame(maxWidth:.infinity)}}
